from collections import deque
from functools import lru_cache

def solve(M, N, discs):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(0, 0, 0)])
    visited = {(0, 0, 0)}
    @lru_cache(None)
    def dfs(x, y, penalty):
        if x == M - 1 and y == N - 1:
            return penalty
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < M and 0 <= ny < N:
                if (nx, ny, penalty + 1) not in visited:
                    visited.add((nx, ny, penalty + 1))
                    queue.append((nx, ny, penalty + 1))
    while queue:
        x, y, penalty = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < M and 0 <= ny < N:
                if (nx, ny, penalty) not in visited:
                    visited.add((nx, ny, penalty))
                    queue.append((nx, ny, penalty))
                    if dfs(nx, ny, penalty) != -1:
                        return dfs(nx, ny, penalty)
    return -1

