def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    p = 2
    while p**2 <= n:
        if primes[p]:
            for i in range(p**2, n + 1, p):
                primes[i] = False
        p += 1
    return [p for p in range(2, n + 1) if primes[p]]

def read_pages(n):
    primes = sieve_of_eratosthenes(n)
    pages = []
    days = []
    for p in primes:
        if n % p != 0:
            pages.append(p)
        while pages and pages[-1] % p == 0:
            pages.pop()
    days.append(pages)
    i = 1
    while pages:
        pages_to_read = []
        for p in pages:
            if p <= i:
                pages_to_read.append(p)
                pages.remove(p)
            else:
                break
        days.append(pages_to_read)
        i += 1
    return days

