import random
from collections import defaultdict, deque

def expected_toll_tax(n, roads):
    graph = defaultdict(list)
    for u, v, c in roads:
        graph[u].append((v, c))
        graph[v].append((u, c))
    visited = [0] * (n + 1)
    for _ in range(n - 1):
        u, v = random.sample(range(1, n + 1), 2)
        while visited[u] + visited[v] >= 2:
            u, v = random.sample(range(1, n + 1), 2)
        visited[u] += 1
        visited[v] += 1
        for node, cost in graph[u]:
            if node == v:
                graph[u].remove((node, cost))
                graph[v].remove((u, cost))
        for node, cost in graph[v]:
            if node == u:
                graph[v].remove((node, cost))
                graph[u].remove((v, cost))
    total_cost = 0
    queue = deque([(1, 0)])
    visited[1] = 1
    while queue:
        node, cost = queue.popleft()
        total_cost += cost
        for neighbor, c in graph[node]:
            if not visited[neighbor]:
                queue.append((neighbor, c))
                visited[neighbor] = 1
    return total_cost / (n - 1)

